Play(61);   // The voice "It\'s" is the name of "61" song in the folder of SD card\n      while(QueryPlayStatus() != 0);  // play next song before the previous song is played out\n      SpecifyMusicPlay(b);  // play the name of "b" song in the folder of SD card\n      while(QueryPlayStatus() != 0);\n      SpecifyMusicPlay(c);  //  play the name of "c" song in the folder of SD card\n      while(QueryPlayStatus() != 0);\n    }\n  }\n    delay(1000);\n}\n\n'})}),"\n",(0,o.jsx)(n.h2,{id:"recursos",children:"Recursos"}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.a,{href:"https://github.com/Seeed-Studio/IRSendRev",children:"Github: IRSendRev"})}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.a,{href:"https://github.com/Seeed-Studio/Grove_Serial_MP3_Player_V2.0",children:"Github: MP3"})}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.a,{href:"https://github.com/Seeed-Studio/RTC_DS1307",children:"Github: RTC"})}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.a,{href:"https://files.seeedstudio.com/wiki/Grove_Speech_Recognizer_Kit_for_Arduino/res/Sound_file.zip",children:"Arquivos de som da transmiss\xe3o"})}),"\n"]}),"\n"]}),"\n",(0,o.jsx)(n.h2,{id:"suporte-t\xe9cnico--discuss\xe3o-de-produto",children:"Suporte T\xe9cnico & Discuss\xe3o de Produto"}),"\n",(0,o.jsx)(n.p,{children:"Obrigado por escolher nossos produtos! Estamos aqui para fornecer diferentes tipos de suporte para garantir que sua experi\xeancia com nossos produtos seja a mais tranquila poss\xedvel. Oferecemos v\xe1rios canais de comunica\xe7\xe3o para atender a diferentes prefer\xeancias e necessidades."}),"\n",(0,o.jsxs)("div",{class:"button_tech_support_container",children:[(0,o.jsx)("a",{href:"https://forum.seeedstudio.com/",class:"button_forum"}),(0,o.jsx)("a",{href:"https://www.seeedstudio.com/contacts",class:"button_e